UNITS = [{"id": "PEDS-U001", "ch": 1, "n": 1, "title": "Newborn Period & Birth Weights", "sec": "Definitions · p2", "guide": "Newborn period = first 4 weeks: 1st week is early, next 3 weeks are late. Birth weight categories: LBW < 2.5 kg, VLBW < 1.5 kg, ELBW < 1 kg. (Book p2)", "qs": ["PEDS-C1-001", "PEDS-C1-002", "PEDS-C1-003", "PEDS-C1-004", "PEDS-C1-005", "PEDS-C1-006"]}, {"id": "PEDS-U002", "ch": 1, "n": 2, "title": "SGA & IUGR: Identification", "sec": "Intrauterine Growth Retardation · p2", "guide": "SGA can be constitutional (normal) or pathological (IUGR). Identification points of IUGR: loose skin folds, skin peeling, thin umbilical cord. (Book p2)", "qs": ["PEDS-C1-007", "PEDS-C1-008", "PEDS-C1-009", "PEDS-C1-010", "PEDS-C1-011"]}, {"id": "PEDS-U003", "ch": 1, "n": 3, "title": "Symmetrical vs Asymmetrical IUGR", "sec": "IUGR Types · p2", "guide": "Symmetrical: maternal etiology (uteroplacental insufficiency), onset 2nd-3rd trimester, brain-sparing present (normal head, small body), good outcome. Asymmetrical: fetal etiology (trisomy, organ anomalies), onset 1st trimester, no brain-sparing (uniformly small), poor outcome. (Book p2)", "qs": ["PEDS-C1-012", "PEDS-C1-013", "PEDS-C1-014", "PEDS-C1-015", "PEDS-C1-016", "PEDS-C1-017", "PEDS-C1-018", "PEDS-C1-019", "PEDS-C1-020"]}, {"id": "PEDS-U004", "ch": 1, "n": 4, "title": "Assessment of IUGR", "sec": "Assessment of IUGR · p2", "guide": "New AIMS intrauterine growth curves: LGA = upper percentile curve, SGA = lower percentile curve; male and female charts are different. Ponderal index (PI) = weight (g) / [length (cm)] cubed x 100: >2 = symmetrical IUGR, <2 = asymmetrical IUGR. (Book p2)", "qs": ["PEDS-C1-021", "PEDS-C1-022", "PEDS-C1-023", "PEDS-C1-024", "PEDS-C1-025", "PEDS-C1-026"]}, {"id": "PEDS-U005", "ch": 1, "n": 5, "title": "Preterm Baby: Classification & Antenatal", "sec": "Preterm Baby · p3", "guide": "Preterm < 37 wks, term 37-41 wks, post-term 42 wks onwards. Antenatal assessment of gestation is based on mother's LMP and 1st trimester ultrasound scan. (Book p3)", "qs": ["PEDS-C1-027", "PEDS-C1-028", "PEDS-C1-029", "PEDS-C1-030", "PEDS-C1-031"]}, {"id": "PEDS-U006", "ch": 1, "n": 6, "title": "ENBS & Physical Maturity", "sec": "Post Natal Assessment · p3", "guide": "Expanded New Ballard Score (ENBS) is postnatal, based on neuromuscular maturity + physical maturity. Total range -10 to +50 (-10 = 20 wks, +50 = 44 wks), accuracy +/-1 week. Physical maturity: each sign scored -1 to +5, and scores map to gestation (0 = 24 wks, 10 = 28 wks, 30 = 36 wks, 45 = 42 wks). (Book p3)", "qs": ["PEDS-C1-032", "PEDS-C1-033", "PEDS-C1-034", "PEDS-C1-035", "PEDS-C1-036", "PEDS-C1-037", "PEDS-C1-038", "PEDS-C1-039", "PEDS-C1-040", "PEDS-C1-041", "PEDS-C1-042", "PEDS-C1-043", "PEDS-C1-044", "PEDS-C1-045", "PEDS-C1-046", "PEDS-C1-047", "PEDS-C1-048", "PEDS-C1-049", "PEDS-C1-050"]}, {"id": "PEDS-U007", "ch": 1, "n": 7, "title": "Preterm vs Term: 11 Differences", "sec": "Differences Preterm & Term · p4", "guide": "Preterm: extended posture, square window negative, no arm recoil, scarf sign positive (elbow crosses midline), obtuse popliteal angle, heel reaches ear, breast buds <5 mm, labia minora visible, empty scrotum, abundant lanugo, slow pinna recoil. Term: the opposite of all; testes fully descended by 36 wks. (Book p4)", "qs": ["PEDS-C1-051", "PEDS-C1-052", "PEDS-C1-053", "PEDS-C1-054", "PEDS-C1-055", "PEDS-C1-056", "PEDS-C1-057", "PEDS-C1-058", "PEDS-C1-059", "PEDS-C1-060", "PEDS-C1-061", "PEDS-C1-062", "PEDS-C1-063", "PEDS-C1-064"]}, {"id": "PEDS-U008", "ch": 1, "n": 8, "title": "Complications of Preterm Birth", "sec": "Complications of Preterm Birth · p4", "guide": "Organ immaturity causes RDS (surfactant deficiency), NEC, IVH (germinal matrix bleeding into ventricles) and kernicterus (bilirubin crosses immature BBB -> brain damage). Decreased nutrient reserve causes hypoglycemia, anemia (low iron stores) and hypothermia. (Book p4)", "qs": ["PEDS-C1-065", "PEDS-C1-066", "PEDS-C1-067", "PEDS-C1-068", "PEDS-C1-069", "PEDS-C1-070", "PEDS-C1-071", "PEDS-C1-072"]}, {"id": "PEDS-U009", "ch": 1, "n": 9, "title": "APGAR Scoring", "sec": "Normal Observations in a Newborn · p4", "guide": "APGAR = Activity, Pulse, Grimace, Appearance, Respiratory effort; each 0-2, total 0-10. Timing: 1 min after birth, followed by repeats. Normal 7-10/10, low <7/10. Grimace is elicited by irritating nasal mucosa with a nasogastric tube. Normal newborn heart rate: 120-160/min. (Book p4-5)", "qs": ["PEDS-C1-073", "PEDS-C1-074", "PEDS-C1-075", "PEDS-C1-076", "PEDS-C1-077", "PEDS-C1-078", "PEDS-C1-079", "PEDS-C1-080", "PEDS-C1-081", "PEDS-C1-082", "PEDS-C1-083", "PEDS-C1-084", "PEDS-C1-085", "PEDS-C1-086", "PEDS-C1-087", "PEDS-C1-088", "PEDS-C1-089", "PEDS-C1-090", "PEDS-C1-091", "PEDS-C1-092"]}, {"id": "PEDS-U010", "ch": 1, "n": 10, "title": "Vital Signs of Newborn", "sec": "Vital Signs · p5", "guide": "Heart rate >100/min (term 100-160/min, preterm 120-180/min); respiratory rate 40-60/min; CRT <= 3 sec (checked by pressing ball of finger over sternum: blanching of skin, then skin becomes pink); temperature 36.5-37.5 C. (Book p5)", "qs": ["PEDS-C1-093", "PEDS-C1-094", "PEDS-C1-095", "PEDS-C1-096", "PEDS-C1-097", "PEDS-C1-098", "PEDS-C1-099"]}, {"id": "PEDS-U011", "ch": 1, "n": 11, "title": "Normal Skin Findings", "sec": "Normal Findings · p5", "guide": "Erythema toxicum: papulosaquamous lesions, eosinophils, onset >24 hr. Pustular melanosis: pustules + hyperpigmented patches, neutrophils, onset <24 hr. Epithelial inclusion cyst: keratin deposits (milia); palate = Epstein pearls, gum = Bohn's nodules. Mongolian spots: melanocytes in dermis, arrest in neural-crest migration. Salmon patch/stork bite/birthmark: forehead or nape of neck, vascular ectasia. (Book p5)", "qs": ["PEDS-C1-100", "PEDS-C1-101", "PEDS-C1-102", "PEDS-C1-103", "PEDS-C1-104", "PEDS-C1-105", "PEDS-C1-106", "PEDS-C1-107", "PEDS-C1-108", "PEDS-C1-109", "PEDS-C1-110", "PEDS-C1-111", "PEDS-C1-112"]}, {"id": "PEDS-U012", "ch": 1, "n": 12, "title": "Other Normal Findings", "sec": "Normal Findings (contd) · p6", "guide": "Breast engorgement and witch's milk (milk-like nipple discharge); bleeding per vagina in females (uterine shedding after sudden withdrawal of maternal hormones); small subconjunctival/retinal hemorrhage (stress of normal delivery); hymenal skin tags (female); physiological phimosis (male). None require treatment - only reassurance. (Book p6)", "qs": ["PEDS-C1-113", "PEDS-C1-114", "PEDS-C1-115", "PEDS-C1-116", "PEDS-C1-117", "PEDS-C1-118", "PEDS-C1-119"]}, {"id": "PEDS-U013", "ch": 1, "n": 13, "title": "Head Swellings: Caput Succedaneum", "sec": "Head Swellings in Newborn · p6", "guide": "Caput succedaneum: more common; diffuse swelling; superficial; scalp. D/t prolonged labour -> venous congestion -> fluid leakage. Content: fluid. Onset: at birth/soon after. Recovery: 2-3 days. No associations. (Book p6)", "qs": ["PEDS-C1-120", "PEDS-C1-121", "PEDS-C1-122", "PEDS-C1-123", "PEDS-C1-124", "PEDS-C1-125", "PEDS-C1-126", "PEDS-C1-127", "PEDS-C1-128"]}, {"id": "PEDS-U014", "ch": 1, "n": 14, "title": "Cephalohematoma & Subgaleal", "sec": "Head Swellings in Newborn (contd) · p6", "guide": "Cephalohematoma: localised, deep, sub-periosteal; d/t trauma to skull in instrumental delivery; blood; slowly increases after 12-24 hr; recovery 3-8 wks; associated with linear skull fractures and jaundice (heme breakdown). Subgaleal hemorrhage: below galea aponeurotica; vacuum extraction -> separation of scalp layers -> blood accumulation; fluctuant; appears soon after birth; most severe - shock, pallor, jaundice. (Book p6)", "qs": ["PEDS-C1-129", "PEDS-C1-130", "PEDS-C1-131", "PEDS-C1-132", "PEDS-C1-133", "PEDS-C1-134", "PEDS-C1-135", "PEDS-C1-136", "PEDS-C1-137", "PEDS-C1-138", "PEDS-C1-139", "PEDS-C1-140", "PEDS-C1-141", "PEDS-C1-142", "PEDS-C1-143"]}]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C1-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

